export function resolveName(name, nodes, aliases) {
  let target = name;
  const seen = new Set();
  while (Object.hasOwn(aliases, target) && aliases[target] != null) {
    if (seen.has(target)) throw new Error('Alias cycle: ' + target);
    seen.add(target);
    target = aliases[target];
  }
  if (!Object.hasOwn(nodes, target)) throw new Error('Unknown node: ' + target);
  return target;
}

